mapper.insert:
INSERT INTO file_record (
    file_id, owner_id, biz_type, biz_id, original_name, object_key, bucket_name, content_type,
    file_size, file_md5, file_ext, storage_type, upload_type, tags, reference_count, status, created_at, updated_at
)
VALUES (
    #{fileId}, #{ownerId}, #{bizType}, #{bizId}, #{originalName}, #{objectKey}, #{bucketName}, #{contentType},
    #{fileSize}, #{fileMd5}, #{fileExt}, #{storageType}, #{uploadType}, #{tags}, COALESCE(#{referenceCount}, 0), #{status}, #{createdAt}, #{updatedAt}
)

INSERT IGNORE INTO file_reference (
    owner_id, file_id, reference_type, reference_id, created_at, updated_at
)
VALUES (
    #{ownerId}, #{fileId}, #{referenceType}, #{referenceId}, NOW(), NOW()
)

mapper.delete:
DELETE FROM file_reference
WHERE owner_id = #{ownerId}
  AND file_id = #{fileId}
  AND reference_type = #{referenceType}
  AND reference_id = #{referenceId}

mapper.update:
UPDATE file_record
SET reference_count = COALESCE(reference_count, 0) + 1,
    updated_at = NOW()
WHERE owner_id = #{ownerId}
  AND file_id = #{fileId}
  AND status = 'NORMAL'

mapper.select:
SELECT COUNT(*)
FROM file_reference
WHERE owner_id = #{ownerId}
  AND file_id = #{fileId}

SELECT id, file_id, owner_id, biz_type, biz_id, original_name, object_key, bucket_name, content_type,
       file_size, file_md5, file_ext, storage_type, upload_type, tags, COALESCE(reference_count, 0) AS reference_count,
       status, created_at, updated_at
FROM file_record
WHERE owner_id = #{ownerId}
  AND file_md5 = #{fileMd5}
  AND file_size = #{fileSize}
  AND status = 'NORMAL'
ORDER BY id DESC
LIMIT 1

SELECT COUNT(*)
FROM file_record
WHERE owner_id = #{ownerId}
  AND status = #{status}

    AND original_name LIKE CONCAT('%', #{originalName}, '%')


    AND file_ext IN

        #{fileExt}



    AND file_md5 = #{fileMd5}


    AND upload_type = #{uploadType}


    AND biz_type = #{bizType}


    AND biz_id = #{bizId}


    AND (

        FIND_IN_SET(#{tag}, tags)

    )


    AND file_size >= #{minFileSize}


    AND file_size <= #{maxFileSize}


    AND created_at >= #{createdFrom}


    AND created_at <= #{createdTo}

SELECT COUNT(*)
FROM file_record
WHERE owner_id = #{ownerId}
  AND status = 'NORMAL'
  AND created_at >= #{createdAt}

SELECT id, file_id, owner_id, biz_type, biz_id, original_name, object_key, bucket_name, content_type,
       file_size, file_md5, file_ext, storage_type, upload_type, tags, COALESCE(reference_count, 0) AS reference_count,
       status, created_at, updated_at
FROM file_record
WHERE owner_id = #{ownerId}
  AND status = #{status}

    AND original_name LIKE CONCAT('%', #{originalName}, '%')


    AND file_ext IN

        #{fileExt}



    AND file_md5 = #{fileMd5}


    AND upload_type = #{uploadType}


    AND biz_type = #{bizType}


    AND biz_id = #{bizId}


    AND (

        FIND_IN_SET(#{tag}, tags)

    )


    AND file_size >= #{minFileSize}


    AND file_size <= #{maxFileSize}


    AND created_at >= #{createdFrom}


    AND created_at <= #{createdTo}

ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM file_record
WHERE id = #{id}
  AND status = 'DELETED'
